const aiStateLabel={idle:'대기',patrolling:'순찰',defending:'방어',attacking:'공격',reinforcing:'증원',retreating:'후퇴',pursuing:'추격'}
const siteIcon:Record<StrategicSiteKind,string>={command_post:'🎖️',supply_depot:'📦',ammo_depot:'💣',airbase:'✈️',rail_station:'🚉',radar:'📡',field_hospital:'🏥',communications:'📻',fuel_depot:'⛽'}
const forestName:Record<string,string>={northwest:'서북 삼림',northeast:'북동 수림',southeast:'동남 숲',southwest:'서남 숲',blackwood:'검은 숲',eastwood:'동부 대삼림','southern-pines':'남부 소나무숲',riverwood:'강변 수림',waldmark:'발트마르크 숲','fir-ridge':'전나무 능선','deep-east':'심동부 숲','green-belt':'녹색 지대',wolfwood:'늑대 숲','south-march':'남부 변경림','lower-pines':'하부 소나무숲','border-wood':'국경 수림'}
const clampCamera=(c:Camera,w:number,h:number)=>{const vw=w/c.zoom,vh=h/c.zoom;c.x=Math.max(0,Math.min(WORLD.width-vw,c.x));c.y=Math.max(0,Math.min(WORLD.height-vh,c.y))}

function drawPlaceMarker(ctx:CanvasRenderingContext2D,c:Camera,x:number,y:number,emoji:string,label:string){const iconSize=Math.max(16,Math.min(24,18*Math.pow(c.zoom,.15))),labelSize=Math.max(9,Math.min(12,10*Math.pow(c.zoom,.12)));ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`${iconSize/c.zoom}px "Apple Color Emoji","Segoe UI Emoji",sans-serif`;ctx.fillText(emoji,x,y);if(c.zoom>=.45){ctx.font=`600 ${labelSize/c.zoom}px ui-monospace`;const width=ctx.measureText(label).width,pad=4/c.zoom,labelY=y+(iconSize*.75+8)/c.zoom;ctx.fillStyle='#d8d3bcdd';ctx.fillRect(x-width/2-pad,labelY-labelSize*.65/c.zoom,width+pad*2,labelSize*1.35/c.zoom);ctx.fillStyle='#30342f';ctx.fillText(label,x,labelY)}}

function renderMap(ctx:CanvasRenderingContext2D,c:Camera,sites:StrategicSite[]){
  ctx.fillStyle='#a8a58e';ctx.fillRect(0,0,WORLD.width,WORLD.height)
  ctx.strokeStyle='#3a3c3022';ctx.lineWidth=1/c.zoom
  for(let y=80;y<WORLD.height;y+=92){ctx.beginPath();for(let x=0;x<=WORLD.width;x+=25){const yy=y+Math.sin(x*.009+y*.002)*18+Math.cos(x*.003)*11;if(x)ctx.lineTo(x,yy);else ctx.moveTo(x,yy)}ctx.stroke()}
  if(c.zoom>.8){ctx.strokeStyle='#30362d17';for(let x=0;x<WORLD.width;x+=100){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,WORLD.height);ctx.stroke()}for(let y=0;y<WORLD.height;y+=100){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WORLD.width,y);ctx.stroke()}}
  farms.forEach((f,fi)=>{ctx.fillStyle=fi%2?'#aaa17d':'#b2a984';ctx.fillRect(f.x,f.y,f.w,f.h);ctx.strokeStyle='#756f5744';ctx.lineWidth=2/c.zoom;for(let x=f.x+22;x<f.x+f.w;x+=28){ctx.beginPath();ctx.moveTo(x,f.y);ctx.lineTo(x-45,f.y+f.h);ctx.stroke()}drawPlaceMarker(ctx,c,f.x+f.w/2,f.y+f.h/2,'🌾','농경지')})
  hills.forEach(h=>{for(let i=4;i>0;i--){ctx.beginPath();ctx.ellipse(h.x,h.y,h.rx*i/4,h.ry*i/4,-.12,0,Math.PI*2);ctx.strokeStyle=`rgba(91,82,61,${.12+i*.045})`;ctx.lineWidth=2/c.zoom;ctx.stroke()}drawPlaceMarker(ctx,c,h.x,h.y,'⛰️',h.name)})
  forests.forEach((f,i)=>{ctx.beginPath();ctx.roundRect(f.x,f.y,f.w,f.h,70);ctx.fillStyle='#5f6d55';ctx.fill();ctx.strokeStyle='#3d4b3766';ctx.lineWidth=2/c.zoom;ctx.stroke();if(c.zoom>.65){ctx.fillStyle='#26382466';const s=c.zoom>1.25?32:56;for(let x=f.x+25;x<f.x+f.w-15;x+=s)for(let y=f.y+25;y<f.y+f.h-15;y+=s){ctx.beginPath();ctx.arc(x+Math.sin(x*9+y+i)*8,y,c.zoom>1.25?7:5,0,Math.PI*2);ctx.fill()}}drawPlaceMarker(ctx,c,f.x+f.w/2,f.y+f.h/2,'🌲',forestName[f.id]??'삼림')})
  const river=()=>{ctx.beginPath();ctx.moveTo(970,-40);ctx.bezierCurveTo(890,240,1180,390,1060,620);ctx.bezierCurveTo(930,860,1240,1030,1160,1450);ctx.bezierCurveTo(1100,1780,1320,2070,1210,2370);ctx.bezierCurveTo(1140,2780,1450,3000,1370,3440);ctx.bezierCurveTo(1290,3820,1530,4210,1460,4840);ctx.bezierCurveTo(1390,5420,1720,5940,1610,6560);ctx.bezierCurveTo(1510,7210,1920,7740,1800,8420);ctx.bezierCurveTo(1690,9020,2050,9500,1970,10040)}
  const eastRiver=()=>{ctx.beginPath();ctx.moveTo(5260,-40);ctx.bezierCurveTo(5470,420,5250,760,5420,1120);ctx.bezierCurveTo(5580,1490,5350,1920,5500,2300);ctx.bezierCurveTo(5660,2700,5480,3180,5600,3560);ctx.bezierCurveTo(5720,3960,5590,4380,5790,4840);ctx.bezierCurveTo(5980,5360,5790,5940,6000,6500);ctx.bezierCurveTo(6200,7100,5980,7680,6180,8260);ctx.bezierCurveTo(6380,8840,6190,9460,6460,10040)}
  ;[river,eastRiver].forEach(drawRiver=>{ctx.strokeStyle='#506a70';ctx.lineWidth=50;drawRiver();ctx.stroke();ctx.strokeStyle='#82999a';ctx.lineWidth=38;drawRiver();ctx.stroke();ctx.strokeStyle='#cbd6d044';ctx.lineWidth=3;drawRiver();ctx.stroke()})
  roads.forEach(points=>{ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#615e50';ctx.lineWidth=15;ctx.stroke();ctx.strokeStyle='#beb79c';ctx.lineWidth=9;ctx.stroke();if(c.zoom>1.05){ctx.setLineDash([16,14]);ctx.strokeStyle='#514e4177';ctx.lineWidth=1.5;ctx.stroke();ctx.setLineDash([])}})
  bridges.forEach(b=>{ctx.save();ctx.translate(b.x,b.y);ctx.fillStyle='#333832';ctx.fillRect(-43,-11,86,22);ctx.strokeStyle='#d1c59b';ctx.lineWidth=2;ctx.strokeRect(-39,-7,78,14);ctx.restore()})
  lakes.forEach(l=>{ctx.beginPath();ctx.ellipse(l.x,l.y,l.rx,l.ry,.08,0,Math.PI*2);ctx.fillStyle='#768f91';ctx.fill();ctx.strokeStyle='#526b6e';ctx.lineWidth=4/c.zoom;ctx.stroke();ctx.beginPath();ctx.ellipse(l.x,l.y,l.rx-14,l.ry-14,.08,0,Math.PI*2);ctx.strokeStyle='#b9c7bd55';ctx.lineWidth=2/c.zoom;ctx.stroke();drawPlaceMarker(ctx,c,l.x,l.y,'🌊',l.name)})
  cities.forEach(city=>{const r=city.major?30:20;ctx.fillStyle='#393d37';ctx.fillRect(city.x-r,city.y-r,r*2,r*2);ctx.strokeStyle='#d4cfb7';ctx.lineWidth=3/c.zoom;ctx.strokeRect(city.x-r+4,city.y-r+4,r*2-8,r*2-8);if(c.zoom>1.15){for(let i=-1;i<=1;i++)for(let j=-1;j<=1;j++){ctx.fillStyle='#4c5047';ctx.fillRect(city.x+i*14-4,city.y+j*14-4,8,8)}}drawPlaceMarker(ctx,c,city.x,city.y,city.major?'🏙️':'🏘️',city.name)})
  villages.forEach(v=>{ctx.fillStyle='#5e5a4c';for(let i=0;i<5;i++){const ox=(i%3)*13-13,oy=Math.floor(i/3)*13-6;ctx.fillRect(v.x+ox-5,v.y+oy-5,10,10)}ctx.strokeStyle='#c2b997';ctx.lineWidth=1/c.zoom;ctx.beginPath();ctx.arc(v.x,v.y,29,0,Math.PI*2);ctx.stroke();drawPlaceMarker(ctx,c,v.x,v.y,'🏠',v.name)})
  sites.forEach(site=>{const color=site.owner==='player'?'#315e68':site.owner==='enemy'?'#8b453d':'#756f5c',r=Math.max(30,13/c.zoom);ctx.beginPath();ctx.arc(site.x,site.y,site.captureRadius,0,Math.PI*2);ctx.fillStyle=`${color}12`;ctx.fill();ctx.strokeStyle=`${color}55`;ctx.lineWidth=1.5/c.zoom;ctx.setLineDash([8/c.zoom,7/c.zoom]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#e3ddc7';ctx.strokeStyle=color;ctx.lineWidth=5/c.zoom;ctx.fillRect(site.x-r,site.y-r,r*2,r*2);ctx.strokeRect(site.x-r,site.y-r,r*2,r*2);ctx.fillStyle=color;ctx.font=`${Math.max(16,14/c.zoom)}px "Apple Color Emoji","Segoe UI Emoji",sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(siteIcon[site.kind],site.x,site.y);if(c.zoom>=.45){ctx.fillStyle='#292d29';ctx.font=`600 ${Math.max(10,8/c.zoom)}px ui-monospace`;ctx.fillText(site.name,site.x,site.y+r+17/c.zoom)}if(site.captureProgress>0){ctx.beginPath();ctx.arc(site.x,site.y,r+9/c.zoom,-Math.PI/2,-Math.PI/2+Math.PI*2*site.captureProgress/100);ctx.strokeStyle=site.capturingFaction==='player'?'#65aaba':'#c96759';ctx.lineWidth=5/c.zoom;ctx.stroke()}})
  ctx.beginPath();ctx.moveTo(1320,0);ctx.bezierCurveTo(1260,310,1400,520,1300,760);ctx.bezierCurveTo(1220,1180,1420,1480,1320,1900);ctx.bezierCurveTo(1220,2360,1570,2780,1450,3250);ctx.bezierCurveTo(1320,3740,1690,4240,1580,4800);ctx.bezierCurveTo(1460,5480,1940,6060,1740,6740);ctx.bezierCurveTo(1560,7420,2170,8110,1960,8760);ctx.bezierCurveTo(1840,9270,2250,9650,2180,10000);ctx.strokeStyle='#923f34bb';ctx.lineWidth=5/c.zoom;ctx.setLineDash([15/c.zoom,10/c.zoom]);ctx.stroke();ctx.setLineDash([])
}

function renderUnits(ctx:CanvasRenderingContext2D,units:Unit[],formations:Formation[],selectedIds:number[],selectedFormationId:string|null,c:Camera,now:number,visibleEnemies:Set<number>){
  const renderableUnits=units.filter(u=>u.faction==='player'||visibleEnemies.has(u.id))
  renderableUnits.forEach(u=>{if(!u.path.length||u.faction==='enemy')return;ctx.beginPath();ctx.moveTo(u.x,u.y);u.path.forEach(p=>ctx.lineTo(p.x,p.y));ctx.strokeStyle=selectedIds.includes(u.id)?'#e8ba4a':'#294f5f88';ctx.lineWidth=2.4/c.zoom;ctx.setLineDash([11/c.zoom,8/c.zoom]);ctx.stroke();ctx.setLineDash([]);const t=u.path[u.path.length-1];ctx.beginPath();ctx.arc(t.x,t.y,12/c.zoom,0,Math.PI*2);ctx.stroke()})
  formations.filter(f=>!f.id.startsWith('enemy-')||f.unitIds.some(id=>visibleEnemies.has(id))).forEach(f=>{const center=formationCenter(f,units),selected=f.id===selectedFormationId,enemy=f.id.startsWith('enemy-');ctx.beginPath();ctx.arc(center.x,center.y,62,0,Math.PI*2);ctx.strokeStyle=selected?'#f0c65a':enemy?'#874b45bb':'#415e61aa';ctx.lineWidth=(selected?3:1.5)/c.zoom;ctx.setLineDash([8/c.zoom,6/c.zoom]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=selected?'#2b3529ee':enemy?'#4b2927dd':'#263b3bdd';ctx.fillRect(center.x-45,center.y-76,90,21);ctx.fillStyle=selected?'#f0cf70':enemy?'#e0b4aa':'#c4d1c9';ctx.font='600 10px ui-monospace';ctx.textAlign='center';ctx.fillText(`${f.name} · ${formationLabel[f.type]}`,center.x,center.y-62)})
  renderableUnits.forEach(u=>{const selected=selectedIds.includes(u.id)||!!(selectedFormationId&&u.parentFormationId===selectedFormationId),destroyed=u.combatState==='destroyed',w=c.zoom<.55?50:76,h=c.zoom<.55?29:42;if(selected){ctx.beginPath();ctx.arc(u.x,u.y,42+Math.sin(now*.004)*3,0,Math.PI*2);ctx.fillStyle='#eab73c2b';ctx.fill();ctx.strokeStyle='#f0c65a';ctx.lineWidth=2.5/c.zoom;ctx.stroke()}ctx.fillStyle=destroyed?'#3c3c36':u.faction==='enemy'?'#693a35':u.type==='기계화'?'#274b4b':'#203d4a';ctx.fillRect(u.x-w/2,u.y-h/2,w,h);ctx.strokeStyle=selected?'#f2c85b':u.faction==='enemy'?'#d2aaa0':'#adc0bd';ctx.lineWidth=2.5/c.zoom;ctx.strokeRect(u.x-w/2,u.y-h/2,w,h);ctx.fillStyle='#edf1e9';ctx.textAlign='center';ctx.font=`700 ${c.zoom<.55?12:16}px ui-monospace`;ctx.fillText(destroyed?'×':unitCode[u.type],u.x,u.y+6);ctx.fillStyle='#d9ddd2';ctx.fillRect(u.x-w/2,u.y-h/2-9,w,4);ctx.fillStyle=u.faction==='enemy'?'#a54b40':'#668e67';ctx.fillRect(u.x-w/2,u.y-h/2-9,w*u.strength.current/u.strength.max,4);if(c.zoom>=.52){ctx.fillStyle=u.faction==='enemy'?'#4f2723':'#182428';ctx.font='600 12px ui-monospace';ctx.fillText(c.zoom>1.25?`${u.name} · ${u.combatState}`:u.callSign,u.x,u.y+h/2+18)}if(c.zoom>1.35&&!destroyed){ctx.fillStyle=u.faction==='enemy'?'#582e29':'#1c343d';const count=u.type==='보병'?5:u.type==='기갑'||u.type==='기계화'?3:2;for(let i=0;i<count;i++){ctx.beginPath();ctx.arc(u.x+(i-(count-1)/2)*11,u.y+h/2+33,3,0,Math.PI*2);ctx.fill()}}})
}

function renderContacts(ctx:CanvasRenderingContext2D,knowledge:KnowledgeBase,c:Camera,time:number){Object.values(knowledge.contacts).filter(contact=>contact.state==='detected'||contact.state==='lost').forEach(contact=>{const p=contact.lastKnownPosition,size=(contact.state==='detected'?22:17)/c.zoom;ctx.beginPath();ctx.arc(p.x,p.y,size*1.2,0,Math.PI*2);ctx.strokeStyle=contact.state==='detected'?'#d9a94f':'#a08e70';ctx.lineWidth=2/c.zoom;ctx.setLineDash(contact.state==='lost'?[5/c.zoom,5/c.zoom]:[]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=ctx.strokeStyle;ctx.font=`700 ${size}px ui-monospace`;ctx.textAlign='center';ctx.fillText(contact.state==='detected'?'⚠':'×',p.x,p.y+6/c.zoom);if(c.zoom>=.55){ctx.font=`600 ${10/c.zoom}px ui-monospace`;ctx.fillText(contact.state==='detected'?'적 접촉':`마지막 확인 ${Math.max(0,Math.floor(time-contact.lastSeenAt))}분 전`,p.x,p.y+34/c.zoom)}})}
function renderFrontline(ctx:CanvasRenderingContext2D,units:Unit[],c:Camera){const points=frontlinePoints(units);if(points.length<2)return;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#d0a95777';ctx.lineWidth=7/c.zoom;ctx.setLineDash([24/c.zoom,15/c.zoom]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#5f4c2dcc';ctx.font=`700 ${10/c.zoom}px ui-monospace`;ctx.textAlign='center';points.forEach((p,i)=>{if(i%2===0)ctx.fillText('CONTACT LINE',p.x,p.y-13/c.zoom)})}
function renderSupplyOverlay(ctx:CanvasRenderingContext2D,routes:SupplyRoute[],units:Unit[],sites:StrategicSite[],c:Camera){
  routes.filter(r=>r.faction==='player').forEach(route=>{ctx.beginPath();ctx.moveTo(route.from.x,route.from.y);ctx.lineTo(route.to.x,route.to.y);ctx.strokeStyle=route.connected?'#64b8a3cc':'#b96656aa';ctx.lineWidth=(route.connected?5:3)/c.zoom;ctx.setLineDash(route.connected?[]:[14/c.zoom,10/c.zoom]);ctx.stroke();ctx.setLineDash([])})
  units.filter(u=>u.faction==='player'&&u.supply.sourceId).forEach(u=>{const source=sites.find(site=>site.id===u.supply.sourceId);if(source){ctx.beginPath();ctx.moveTo(source.x,source.y);ctx.lineTo(u.x,u.y);ctx.strokeStyle=u.supply.connected?'#89c8a566':'#b95a4d55';ctx.lineWidth=1.5/c.zoom;ctx.setLineDash([7/c.zoom,7/c.zoom]);ctx.stroke();ctx.setLineDash([])}const ammo=Math.round(u.supply.ammunition/u.supply.maxAmmunition*100),fuel=Math.round(u.supply.fuel/u.supply.maxFuel*100),color=u.supply.state==='SUPPLIED'?'#74b68e':u.supply.state==='LOW_SUPPLY'?'#d0ad55':'#d06455';ctx.textAlign='center';if(c.zoom<.75){ctx.beginPath();ctx.arc(u.x,u.y,7/c.zoom,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();return}if(c.zoom<1.15){ctx.fillStyle='#14201ddd';ctx.fillRect(u.x-55/c.zoom,u.y+31/c.zoom,110/c.zoom,18/c.zoom);ctx.strokeStyle=color;ctx.lineWidth=1/c.zoom;ctx.strokeRect(u.x-55/c.zoom,u.y+31/c.zoom,110/c.zoom,18/c.zoom);ctx.fillStyle=color;ctx.font=`600 ${8/c.zoom}px ui-monospace`;ctx.fillText(`탄약 ${ammo}% · 연료 ${fuel}%`,u.x,u.y+43/c.zoom);return}ctx.fillStyle='#14201ddd';ctx.fillRect(u.x-52/c.zoom,u.y+31/c.zoom,104/c.zoom,32/c.zoom);ctx.strokeStyle=color;ctx.lineWidth=1/c.zoom;ctx.strokeRect(u.x-52/c.zoom,u.y+31/c.zoom,104/c.zoom,32/c.zoom);ctx.fillStyle=color;ctx.font=`600 ${9/c.zoom}px ui-monospace`;ctx.fillText(`탄약 ${ammo}% · 연료 ${fuel}%`,u.x,u.y+44/c.zoom);ctx.fillText(u.supply.state.replaceAll('_',' '),u.x,u.y+57/c.zoom)})
}

function renderOrders(ctx:CanvasRenderingContext2D,orders:Order[],units:Unit[],formations:Formation[],c:Camera){orders.filter(o=>o.issuerId==='player'&&o.destination&&!['completed','cancelled'].includes(o.status)).forEach((o,index)=>{const f=formations.find(v=>v.id===o.formationId),members=units.filter(u=>o.targetUnitIds.includes(u.id));if(!members.length)return;const start=f?formationCenter(f,units):{x:members.reduce((s,u)=>s+u.x,0)/members.length,y:members.reduce((s,u)=>s+u.y,0)/members.length},target=o.destination!,responsive=Math.pow(c.zoom,.35),screenRadius=Math.max(7,Math.min(18,12*responsive))+Math.min(index*1.5,5),screenLine=Math.max(1.2,Math.min(3.2,2.1*responsive)),screenFont=Math.max(8,Math.min(14,10*responsive));ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(target.x,target.y);ctx.strokeStyle=o.status==='executing'?'#e7bd50':'#786f48bb';ctx.lineWidth=screenLine/c.zoom;ctx.setLineDash(o.status==='executing'?[]:o.status==='queued'?[5/c.zoom,10/c.zoom]:[2/c.zoom,7/c.zoom]);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(target.x,target.y,screenRadius/c.zoom,0,Math.PI*2);ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font=`700 ${screenFont/c.zoom}px ui-monospace`;ctx.textAlign='center';ctx.fillText(index?'○':'◎',target.x,target.y+screenFont*.3/c.zoom)})}

function renderCombat(ctx:CanvasRenderingContext2D,engagements:Engagement[],projectiles:Projectile[],units:Unit[],c:Camera){engagements.forEach(e=>{const a=units.find(u=>u.id===e.attackerId),b=units.find(u=>u.id===e.defenderId);if(!a||!b)return;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=e.state==='active'?'#a9473dcc':e.state==='engaging'?'#d2a84caa':'#727b70aa';ctx.lineWidth=1.5/c.zoom;ctx.setLineDash(e.state==='active'?[]:[5/c.zoom,6/c.zoom]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=ctx.strokeStyle;ctx.font=`${16/c.zoom}px sans-serif`;ctx.fillText('⚔',(a.x+b.x)/2,(a.y+b.y)/2) });projectiles.forEach(p=>{const x=p.x+(p.targetX-p.x)*p.progress,y=p.y+(p.targetY-p.y)*p.progress,arc=p.kind==='포병'?Math.sin(p.progress*Math.PI)*-55:0;ctx.beginPath();ctx.arc(x,y+arc,Math.max(2,4/c.zoom),0,Math.PI*2);ctx.fillStyle=p.kind==='포병'?'#e8b64d':'#f3dc87';ctx.fill();ctx.beginPath();ctx.moveTo(x-(p.targetX-p.x)*.025,y-(p.targetY-p.y)*.025+arc);ctx.lineTo(x,y+arc);ctx.strokeStyle='#f5d77caa';ctx.lineWidth=2/c.zoom;ctx.stroke()})}
